import{_ as t,o,c as a,ai as r}from"./chunks/framework.DQi1ytmF.js";const u=JSON.parse('{"title":"Deployment diagnostics","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/diagnostics.md","filePath":"guide/deployment/diagnostics.md"}'),i={name:"guide/deployment/diagnostics.md"};function n(d,e,s,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/guide/deployment/diagnostics.md for this page in Markdown format</div><h1 id="deployment-diagnostics" tabindex="-1">Deployment diagnostics <a class="header-anchor" href="#deployment-diagnostics" aria-label="Permalink to &quot;Deployment diagnostics&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Experimental</p><p>Codes can be added, and their messages can change, between minor versions. Do not match on a message in a CI script: match on the <code>code</code> field of the <code>--json</code> report, which is the part meant to be stable.</p></div><p>Every problem <code>craft-ts check</code> reports carries a code, the concerned runtime or platform, a location, what is wrong and what to change. This page is the reference for the codes; it is verified against the checker, so a code cannot ship undocumented.</p><p><code>error</code> fails the check and the command exits with <code>1</code>. <code>warning</code> is printed and the command still succeeds — warnings cover the heuristics, such as scanning sources for environment variable reads, where a false positive must not block a deployment.</p><p>Read a report with <code>--json</code> when a machine consumes it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft-ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/demo-ssr/craft.deploy.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><h2 id="codes" tabindex="-1">Codes <a class="header-anchor" href="#codes" aria-label="Permalink to &quot;Codes&quot;">​</a></h2><h3 id="craft-deploy-artifact-missing" tabindex="-1"><code>CRAFT_DEPLOY_ARTIFACT_MISSING</code> <a class="header-anchor" href="#craft-deploy-artifact-missing" aria-label="Permalink to &quot;`CRAFT_DEPLOY_ARTIFACT_MISSING`&quot;">​</a></h3><p>The artefact directory does not exist.</p><ul><li><strong>Cause</strong> — The directory the provider would publish has not been produced.</li><li><strong>Fix</strong> — Run the declared build command before checking the artefact.</li></ul><h3 id="craft-deploy-artifact-no-entry" tabindex="-1"><code>CRAFT_DEPLOY_ARTIFACT_NO_ENTRY</code> <a class="header-anchor" href="#craft-deploy-artifact-no-entry" aria-label="Permalink to &quot;`CRAFT_DEPLOY_ARTIFACT_NO_ENTRY`&quot;">​</a></h3><p>The artefact has no browser entry point.</p><ul><li><strong>Cause</strong> — The public directory contains no <code>index.html</code>.</li><li><strong>Fix</strong> — Check the build output directory declared in <code>client.outDir</code>.</li></ul><h3 id="craft-deploy-artifact-no-javascript" tabindex="-1"><code>CRAFT_DEPLOY_ARTIFACT_NO_JAVASCRIPT</code> <a class="header-anchor" href="#craft-deploy-artifact-no-javascript" aria-label="Permalink to &quot;`CRAFT_DEPLOY_ARTIFACT_NO_JAVASCRIPT`&quot;">​</a></h3><p>The artefact contains no JavaScript.</p><ul><li><strong>Cause</strong> — The public directory has no <code>.js</code> or <code>.mjs</code> file, which means the build produced nothing executable.</li><li><strong>Fix</strong> — Check the build command and its output directory.</li></ul><h3 id="craft-deploy-artifact-source-map" tabindex="-1"><code>CRAFT_DEPLOY_ARTIFACT_SOURCE_MAP</code> <a class="header-anchor" href="#craft-deploy-artifact-source-map" aria-label="Permalink to &quot;`CRAFT_DEPLOY_ARTIFACT_SOURCE_MAP`&quot;">​</a></h3><p>The artefact ships source maps.</p><ul><li><strong>Cause</strong> — The source map policy is <code>forbidden</code> and the public directory contains <code>.map</code> files.</li><li><strong>Fix</strong> — Disable source maps in the production build, or relax <code>artifact.sourceMaps</code>.</li></ul><h3 id="craft-deploy-config-load-failed" tabindex="-1"><code>CRAFT_DEPLOY_CONFIG_LOAD_FAILED</code> <a class="header-anchor" href="#craft-deploy-config-load-failed" aria-label="Permalink to &quot;`CRAFT_DEPLOY_CONFIG_LOAD_FAILED`&quot;">​</a></h3><p>The deployment manifest could not be imported.</p><ul><li><strong>Cause</strong> — Loading the manifest threw, or the serialised manifest is not valid JSON. A TypeScript manifest also fails when the running Node cannot strip types and TypeScript is not installed.</li><li><strong>Fix</strong> — Fix the thrown error, or run the CLI under a TypeScript loader, or commit a <code>craft.deploy.json</code> produced by the build.</li></ul><h3 id="craft-deploy-config-not-found" tabindex="-1"><code>CRAFT_DEPLOY_CONFIG_NOT_FOUND</code> <a class="header-anchor" href="#craft-deploy-config-not-found" aria-label="Permalink to &quot;`CRAFT_DEPLOY_CONFIG_NOT_FOUND`&quot;">​</a></h3><p>No deployment manifest found.</p><ul><li><strong>Cause</strong> — No <code>craft.deploy.ts</code>, <code>craft.deploy.mjs</code>, <code>craft.deploy.js</code> or <code>craft.deploy.json</code> was found in the checked directory.</li><li><strong>Fix</strong> — Create a manifest with <code>defineCraftDeployment</code> or point the CLI at one with <code>--config</code>.</li></ul><h3 id="craft-deploy-config-no-default-export" tabindex="-1"><code>CRAFT_DEPLOY_CONFIG_NO_DEFAULT_EXPORT</code> <a class="header-anchor" href="#craft-deploy-config-no-default-export" aria-label="Permalink to &quot;`CRAFT_DEPLOY_CONFIG_NO_DEFAULT_EXPORT`&quot;">​</a></h3><p>The deployment manifest has no default export.</p><ul><li><strong>Cause</strong> — The module loaded but exposes no default export to read.</li><li><strong>Fix</strong> — Add <code>export default defineCraftDeployment({ ... })</code>.</li></ul><h3 id="craft-deploy-deploy-not-confirmed" tabindex="-1"><code>CRAFT_DEPLOY_DEPLOY_NOT_CONFIRMED</code> <a class="header-anchor" href="#craft-deploy-deploy-not-confirmed" aria-label="Permalink to &quot;`CRAFT_DEPLOY_DEPLOY_NOT_CONFIRMED`&quot;">​</a></h3><p>A deployment was requested without confirmation.</p><ul><li><strong>Cause</strong> — <code>craft-ts deploy</code> mutates an infrastructure, so it refuses to run until the plan has been approved explicitly.</li><li><strong>Fix</strong> — Review <code>craft-ts deploy preview</code>, then pass <code>--yes</code> to apply it.</li></ul><h3 id="craft-deploy-env-name-invalid" tabindex="-1"><code>CRAFT_DEPLOY_ENV_NAME_INVALID</code> <a class="header-anchor" href="#craft-deploy-env-name-invalid" aria-label="Permalink to &quot;`CRAFT_DEPLOY_ENV_NAME_INVALID`&quot;">​</a></h3><p>Invalid environment variable name.</p><ul><li><strong>Cause</strong> — A declared name is not an upper snake case identifier, which several platforms reject.</li><li><strong>Fix</strong> — Rename the variable to <code>UPPER_SNAKE_CASE</code>.</li></ul><h3 id="craft-deploy-env-undeclared" tabindex="-1"><code>CRAFT_DEPLOY_ENV_UNDECLARED</code> <a class="header-anchor" href="#craft-deploy-env-undeclared" aria-label="Permalink to &quot;`CRAFT_DEPLOY_ENV_UNDECLARED`&quot;">​</a></h3><p>An environment variable is read but not declared.</p><ul><li><strong>Cause</strong> — The module graph of the runtime entry reads a variable the manifest does not list, so no provider can know it must be set.</li><li><strong>Fix</strong> — Declare the variable in <code>env</code>, or stop reading it from the runtime entry.</li></ul><h3 id="craft-deploy-env-value-forbidden" tabindex="-1"><code>CRAFT_DEPLOY_ENV_VALUE_FORBIDDEN</code> <a class="header-anchor" href="#craft-deploy-env-value-forbidden" aria-label="Permalink to &quot;`CRAFT_DEPLOY_ENV_VALUE_FORBIDDEN`&quot;">​</a></h3><p>An environment variable carries a value.</p><ul><li><strong>Cause</strong> — The manifest is committed and read by every provider, so it declares names and requirements only.</li><li><strong>Fix</strong> — Remove the value and provide it through the CI or the provider secret store.</li></ul><h3 id="craft-deploy-function-id-duplicate" tabindex="-1"><code>CRAFT_DEPLOY_FUNCTION_ID_DUPLICATE</code> <a class="header-anchor" href="#craft-deploy-function-id-duplicate" aria-label="Permalink to &quot;`CRAFT_DEPLOY_FUNCTION_ID_DUPLICATE`&quot;">​</a></h3><p>A server-function identifier is declared twice.</p><ul><li><strong>Cause</strong> — The identifier is the routing key of the protocol, so a duplicate makes the exposed contract ambiguous.</li><li><strong>Fix</strong> — Keep one declaration per identifier.</li></ul><h3 id="craft-deploy-function-id-unknown" tabindex="-1"><code>CRAFT_DEPLOY_FUNCTION_ID_UNKNOWN</code> <a class="header-anchor" href="#craft-deploy-function-id-unknown" aria-label="Permalink to &quot;`CRAFT_DEPLOY_FUNCTION_ID_UNKNOWN`&quot;">​</a></h3><p>A declared server-function identifier is not in the registry entry.</p><ul><li><strong>Cause</strong> — The identifier does not appear in the module graph of <code>functions.entry</code>.</li><li><strong>Fix</strong> — Register the function in the entry, or remove the identifier from the manifest.</li></ul><h3 id="craft-deploy-health-path-missing" tabindex="-1"><code>CRAFT_DEPLOY_HEALTH_PATH_MISSING</code> <a class="header-anchor" href="#craft-deploy-health-path-missing" aria-label="Permalink to &quot;`CRAFT_DEPLOY_HEALTH_PATH_MISSING`&quot;">​</a></h3><p>The health route is not served by the SSR entry.</p><ul><li><strong>Cause</strong> — The path declared as <code>server.healthPath</code> was not found in the module graph of the SSR entry.</li><li><strong>Fix</strong> — Serve the declared path, or align the manifest with the path the server exposes.</li></ul><h3 id="craft-deploy-manifest-invalid-field" tabindex="-1"><code>CRAFT_DEPLOY_MANIFEST_INVALID_FIELD</code> <a class="header-anchor" href="#craft-deploy-manifest-invalid-field" aria-label="Permalink to &quot;`CRAFT_DEPLOY_MANIFEST_INVALID_FIELD`&quot;">​</a></h3><p>A manifest field has an invalid value.</p><ul><li><strong>Cause</strong> — The field exists but its type or its shape does not match the contract.</li><li><strong>Fix</strong> — Correct the value reported by <code>path</code>; the message states what was expected.</li></ul><h3 id="craft-deploy-manifest-missing-field" tabindex="-1"><code>CRAFT_DEPLOY_MANIFEST_MISSING_FIELD</code> <a class="header-anchor" href="#craft-deploy-manifest-missing-field" aria-label="Permalink to &quot;`CRAFT_DEPLOY_MANIFEST_MISSING_FIELD`&quot;">​</a></h3><p>A required manifest field is missing.</p><ul><li><strong>Cause</strong> — A field the runtime or the providers need is absent.</li><li><strong>Fix</strong> — Add the field reported by <code>path</code>.</li></ul><h3 id="craft-deploy-manifest-not-an-object" tabindex="-1"><code>CRAFT_DEPLOY_MANIFEST_NOT_AN_OBJECT</code> <a class="header-anchor" href="#craft-deploy-manifest-not-an-object" aria-label="Permalink to &quot;`CRAFT_DEPLOY_MANIFEST_NOT_AN_OBJECT`&quot;">​</a></h3><p>The manifest is not an object.</p><ul><li><strong>Cause</strong> — The default export or the parsed JSON is not a plain object.</li><li><strong>Fix</strong> — Export the object returned by <code>defineCraftDeployment</code>.</li></ul><h3 id="craft-deploy-manifest-section-missing" tabindex="-1"><code>CRAFT_DEPLOY_MANIFEST_SECTION_MISSING</code> <a class="header-anchor" href="#craft-deploy-manifest-section-missing" aria-label="Permalink to &quot;`CRAFT_DEPLOY_MANIFEST_SECTION_MISSING`&quot;">​</a></h3><p>The runtime section is missing.</p><ul><li><strong>Cause</strong> — Each runtime requires its own section: <code>static</code> and <code>client</code>, <code>server</code>, <code>worker</code> or <code>lambda</code>.</li><li><strong>Fix</strong> — Add the section the runtime requires.</li></ul><h3 id="craft-deploy-manifest-section-unexpected" tabindex="-1"><code>CRAFT_DEPLOY_MANIFEST_SECTION_UNEXPECTED</code> <a class="header-anchor" href="#craft-deploy-manifest-section-unexpected" aria-label="Permalink to &quot;`CRAFT_DEPLOY_MANIFEST_SECTION_UNEXPECTED`&quot;">​</a></h3><p>A section does not belong to this runtime.</p><ul><li><strong>Cause</strong> — A section of another runtime is present; nothing would ever execute it.</li><li><strong>Fix</strong> — Remove the section, or change the runtime to the one that uses it.</li></ul><h3 id="craft-deploy-manifest-unknown-platform" tabindex="-1"><code>CRAFT_DEPLOY_MANIFEST_UNKNOWN_PLATFORM</code> <a class="header-anchor" href="#craft-deploy-manifest-unknown-platform" aria-label="Permalink to &quot;`CRAFT_DEPLOY_MANIFEST_UNKNOWN_PLATFORM`&quot;">​</a></h3><p>Unknown platform.</p><ul><li><strong>Cause</strong> — <code>platform</code> is not part of the documented platform list.</li><li><strong>Fix</strong> — Pick a supported platform, or open an issue to add it to the matrix.</li></ul><h3 id="craft-deploy-manifest-unknown-runtime" tabindex="-1"><code>CRAFT_DEPLOY_MANIFEST_UNKNOWN_RUNTIME</code> <a class="header-anchor" href="#craft-deploy-manifest-unknown-runtime" aria-label="Permalink to &quot;`CRAFT_DEPLOY_MANIFEST_UNKNOWN_RUNTIME`&quot;">​</a></h3><p>Unknown runtime.</p><ul><li><strong>Cause</strong> — <code>runtime</code> is not one of <code>static</code>, <code>node</code>, <code>worker</code> or <code>lambda</code>.</li><li><strong>Fix</strong> — Pick one of the four supported runtimes.</li></ul><h3 id="craft-deploy-node-builtin-import" tabindex="-1"><code>CRAFT_DEPLOY_NODE_BUILTIN_IMPORT</code> <a class="header-anchor" href="#craft-deploy-node-builtin-import" aria-label="Permalink to &quot;`CRAFT_DEPLOY_NODE_BUILTIN_IMPORT`&quot;">​</a></h3><p>A Node built-in is imported by a Worker or Lambda entry.</p><ul><li><strong>Cause</strong> — The module graph reachable from the entry imports a Node built-in such as <code>node:fs</code> or <code>node:http</code>, which a Worker runtime does not provide.</li><li><strong>Fix</strong> — Replace the built-in with a Web API, or move the code behind a platform adapter that the Worker entry does not import.</li></ul><h3 id="craft-deploy-path-missing" tabindex="-1"><code>CRAFT_DEPLOY_PATH_MISSING</code> <a class="header-anchor" href="#craft-deploy-path-missing" aria-label="Permalink to &quot;`CRAFT_DEPLOY_PATH_MISSING`&quot;">​</a></h3><p>A declared path does not exist.</p><ul><li><strong>Cause</strong> — An entry point, an output directory or a configuration file declared by the manifest is absent from disk.</li><li><strong>Fix</strong> — Run the build that produces it, or correct the path in the manifest.</li></ul><h3 id="craft-deploy-platform-mismatch" tabindex="-1"><code>CRAFT_DEPLOY_PLATFORM_MISMATCH</code> <a class="header-anchor" href="#craft-deploy-platform-mismatch" aria-label="Permalink to &quot;`CRAFT_DEPLOY_PLATFORM_MISMATCH`&quot;">​</a></h3><p>The requested platform is not the manifest platform.</p><ul><li><strong>Cause</strong> — <code>--platform</code> was passed with a value the manifest does not declare.</li><li><strong>Fix</strong> — Drop the flag, or change <code>platform</code> in the manifest.</li></ul><h3 id="craft-deploy-protocol-version-unsupported" tabindex="-1"><code>CRAFT_DEPLOY_PROTOCOL_VERSION_UNSUPPORTED</code> <a class="header-anchor" href="#craft-deploy-protocol-version-unsupported" aria-label="Permalink to &quot;`CRAFT_DEPLOY_PROTOCOL_VERSION_UNSUPPORTED`&quot;">​</a></h3><p>Unsupported manifest protocol version.</p><ul><li><strong>Cause</strong> — The serialised manifest was produced by another version of the protocol.</li><li><strong>Fix</strong> — Rebuild the manifest with the current CraftTS tooling, or follow the migration notes.</li></ul><h3 id="craft-deploy-provider-capability-missing" tabindex="-1"><code>CRAFT_DEPLOY_PROVIDER_CAPABILITY_MISSING</code> <a class="header-anchor" href="#craft-deploy-provider-capability-missing" aria-label="Permalink to &quot;`CRAFT_DEPLOY_PROVIDER_CAPABILITY_MISSING`&quot;">​</a></h3><p>The provider does not support this runtime.</p><ul><li><strong>Cause</strong> — The capability required by the runtime, and by the static mode when relevant, is not offered by the provider.</li><li><strong>Fix</strong> — Choose a provider that declares the capability, or change the runtime or the static mode.</li></ul><h3 id="craft-deploy-provider-credentials-missing" tabindex="-1"><code>CRAFT_DEPLOY_PROVIDER_CREDENTIALS_MISSING</code> <a class="header-anchor" href="#craft-deploy-provider-credentials-missing" aria-label="Permalink to &quot;`CRAFT_DEPLOY_PROVIDER_CREDENTIALS_MISSING`&quot;">​</a></h3><p>The provider has no credentials.</p><ul><li><strong>Cause</strong> — A credential the platform requires is absent from the environment. The tooling never stores one, so it can only report the name it expected.</li><li><strong>Fix</strong> — Export the named variable in the shell or the CI secret store, then run the command again.</li></ul><h3 id="craft-deploy-provider-invalid-module" tabindex="-1"><code>CRAFT_DEPLOY_PROVIDER_INVALID_MODULE</code> <a class="header-anchor" href="#craft-deploy-provider-invalid-module" aria-label="Permalink to &quot;`CRAFT_DEPLOY_PROVIDER_INVALID_MODULE`&quot;">​</a></h3><p>The provider package does not export a provider.</p><ul><li><strong>Cause</strong> — The module loaded but exposes no <code>createCraftDeploymentProvider</code> factory.</li><li><strong>Fix</strong> — Export <code>createCraftDeploymentProvider(options?)</code> returning a <code>CraftDeploymentProvider</code>.</li></ul><h3 id="craft-deploy-provider-not-installed" tabindex="-1"><code>CRAFT_DEPLOY_PROVIDER_NOT_INSTALLED</code> <a class="header-anchor" href="#craft-deploy-provider-not-installed" aria-label="Permalink to &quot;`CRAFT_DEPLOY_PROVIDER_NOT_INSTALLED`&quot;">​</a></h3><p>The provider package is not installed.</p><ul><li><strong>Cause</strong> — The CLI resolves a provider from <code>@craft-ts/deploy-&lt;name&gt;</code> at run time, and that package is absent from the project.</li><li><strong>Fix</strong> — Install the provider package, or point <code>--provider-module</code> at the module that exports it.</li></ul><h3 id="craft-deploy-provider-platform-unsupported" tabindex="-1"><code>CRAFT_DEPLOY_PROVIDER_PLATFORM_UNSUPPORTED</code> <a class="header-anchor" href="#craft-deploy-provider-platform-unsupported" aria-label="Permalink to &quot;`CRAFT_DEPLOY_PROVIDER_PLATFORM_UNSUPPORTED`&quot;">​</a></h3><p>The provider does not target this platform.</p><ul><li><strong>Cause</strong> — The provider cannot deploy to the platform declared by the manifest.</li><li><strong>Fix</strong> — Choose a provider that targets the platform, or change the platform.</li></ul><h3 id="craft-deploy-provider-state-unavailable" tabindex="-1"><code>CRAFT_DEPLOY_PROVIDER_STATE_UNAVAILABLE</code> <a class="header-anchor" href="#craft-deploy-provider-state-unavailable" aria-label="Permalink to &quot;`CRAFT_DEPLOY_PROVIDER_STATE_UNAVAILABLE`&quot;">​</a></h3><p>The provider state cannot be read.</p><ul><li><strong>Cause</strong> — An infrastructure provider reconciles against a recorded state; without it, a deployment cannot tell a creation from an update.</li><li><strong>Fix</strong> — Make the state backend reachable, or initialise it for this stage before deploying.</li></ul><h3 id="craft-deploy-provider-toolchain-missing" tabindex="-1"><code>CRAFT_DEPLOY_PROVIDER_TOOLCHAIN_MISSING</code> <a class="header-anchor" href="#craft-deploy-provider-toolchain-missing" aria-label="Permalink to &quot;`CRAFT_DEPLOY_PROVIDER_TOOLCHAIN_MISSING`&quot;">​</a></h3><p>A tool the provider drives is missing.</p><ul><li><strong>Cause</strong> — The provider shells out to a CLI or imports a runtime package that is not installed.</li><li><strong>Fix</strong> — Install the reported tool, or choose a provider that does not need it.</li></ul><h3 id="craft-deploy-provider-unknown" tabindex="-1"><code>CRAFT_DEPLOY_PROVIDER_UNKNOWN</code> <a class="header-anchor" href="#craft-deploy-provider-unknown" aria-label="Permalink to &quot;`CRAFT_DEPLOY_PROVIDER_UNKNOWN`&quot;">​</a></h3><p>Unknown provider.</p><ul><li><strong>Cause</strong> — The provider name is absent from the capability matrix.</li><li><strong>Fix</strong> — Use a documented provider name, or register the provider before checking.</li></ul><h3 id="craft-deploy-provider-unsupported-resource" tabindex="-1"><code>CRAFT_DEPLOY_PROVIDER_UNSUPPORTED_RESOURCE</code> <a class="header-anchor" href="#craft-deploy-provider-unsupported-resource" aria-label="Permalink to &quot;`CRAFT_DEPLOY_PROVIDER_UNSUPPORTED_RESOURCE`&quot;">​</a></h3><p>The provider has no resource for this part of the manifest.</p><ul><li><strong>Cause</strong> — The runtime, the platform or a declared binding maps to nothing the provider knows how to create.</li><li><strong>Fix</strong> — Remove the declaration, or deploy that part with a provider that supports it.</li></ul><h3 id="craft-deploy-ready-path-missing" tabindex="-1"><code>CRAFT_DEPLOY_READY_PATH_MISSING</code> <a class="header-anchor" href="#craft-deploy-ready-path-missing" aria-label="Permalink to &quot;`CRAFT_DEPLOY_READY_PATH_MISSING`&quot;">​</a></h3><p>The readiness route is not served by the SSR entry.</p><ul><li><strong>Cause</strong> — The path declared as <code>server.readyPath</code> was not found in the module graph of the SSR entry.</li><li><strong>Fix</strong> — Serve the declared path, or align the manifest with the path the server exposes.</li></ul><h3 id="craft-deploy-runtime-mismatch" tabindex="-1"><code>CRAFT_DEPLOY_RUNTIME_MISMATCH</code> <a class="header-anchor" href="#craft-deploy-runtime-mismatch" aria-label="Permalink to &quot;`CRAFT_DEPLOY_RUNTIME_MISMATCH`&quot;">​</a></h3><p>The requested runtime is not the manifest runtime.</p><ul><li><strong>Cause</strong> — <code>--runtime</code> was passed with a value the manifest does not declare.</li><li><strong>Fix</strong> — Drop the flag, or change <code>runtime</code> in the manifest.</li></ul><h3 id="craft-deploy-runtime-platform-incompatible" tabindex="-1"><code>CRAFT_DEPLOY_RUNTIME_PLATFORM_INCOMPATIBLE</code> <a class="header-anchor" href="#craft-deploy-runtime-platform-incompatible" aria-label="Permalink to &quot;`CRAFT_DEPLOY_RUNTIME_PLATFORM_INCOMPATIBLE`&quot;">​</a></h3><p>This platform cannot execute this runtime.</p><ul><li><strong>Cause</strong> — The platform has no execution shape for the declared runtime, for instance a <code>lambda</code> runtime on Cloudflare.</li><li><strong>Fix</strong> — Change the runtime or the platform; the compatibility matrix lists the supported pairs.</li></ul><h3 id="craft-deploy-spa-fallback-missing" tabindex="-1"><code>CRAFT_DEPLOY_SPA_FALLBACK_MISSING</code> <a class="header-anchor" href="#craft-deploy-spa-fallback-missing" aria-label="Permalink to &quot;`CRAFT_DEPLOY_SPA_FALLBACK_MISSING`&quot;">​</a></h3><p>The SPA fallback document is missing from the client output.</p><ul><li><strong>Cause</strong> — A <code>spa</code> deployment answers unknown paths with the fallback document, which is absent from the built output.</li><li><strong>Fix</strong> — Build the client, or correct <code>static.fallback</code>.</li></ul><h3 id="craft-deploy-ssg-routes-missing" tabindex="-1"><code>CRAFT_DEPLOY_SSG_ROUTES_MISSING</code> <a class="header-anchor" href="#craft-deploy-ssg-routes-missing" aria-label="Permalink to &quot;`CRAFT_DEPLOY_SSG_ROUTES_MISSING`&quot;">​</a></h3><p>The SSG mode declares no route.</p><ul><li><strong>Cause</strong> — A <code>ssg</code> deployment pre-renders one HTML file per route and the route list is empty.</li><li><strong>Fix</strong> — List the routes in <code>static.routes</code>, or switch the mode to <code>spa</code>.</li></ul><h3 id="craft-deploy-ssg-route-not-rendered" tabindex="-1"><code>CRAFT_DEPLOY_SSG_ROUTE_NOT_RENDERED</code> <a class="header-anchor" href="#craft-deploy-ssg-route-not-rendered" aria-label="Permalink to &quot;`CRAFT_DEPLOY_SSG_ROUTE_NOT_RENDERED`&quot;">​</a></h3><p>A declared SSG route has no pre-rendered document.</p><ul><li><strong>Cause</strong> — The artefact contains neither <code>&lt;route&gt;.html</code> nor <code>&lt;route&gt;/index.html</code> for a route listed in <code>static.routes</code>.</li><li><strong>Fix</strong> — Run the pre-render step for that route, or remove it from <code>static.routes</code>.</li></ul><h3 id="craft-deploy-ssg-route-not-static" tabindex="-1"><code>CRAFT_DEPLOY_SSG_ROUTE_NOT_STATIC</code> <a class="header-anchor" href="#craft-deploy-ssg-route-not-static" aria-label="Permalink to &quot;`CRAFT_DEPLOY_SSG_ROUTE_NOT_STATIC`&quot;">​</a></h3><p>An SSG route cannot be pre-rendered.</p><ul><li><strong>Cause</strong> — The route is not an absolute literal path: it carries a <code>:param</code>, a wildcard or a query string, so no single HTML file represents it.</li><li><strong>Fix</strong> — Expand the route into its literal paths, or declare it in <code>static.serverRoutes</code>.</li></ul>',131)])])}const f=t(i,[["render",n]]);export{u as __pageData,f as default};
